INSERT INTO posts (id, slug, title, excerpt, category, tags, body_json, body_text, word_count, status, series_id, series_order, is_sample)
VALUES (1, 'inspiration-versus-exploitation-traditional-cultural', 'Inspiration versus exploitation: traditional cultural expressions in fashion', 'Where borrowing from a community’s heritage becomes taking, and what the law can do about it.', 'Fashion law', '["Fashion law","TCEs"]', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Fashion has always borrowed. The question is when borrowing becomes taking, and who gets a say."}]},{"type":"marginNote","attrs":{"kind":"note"},"content":[{"type":"text","text":"the whole question, really"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Why the existing tools fall short"}]},{"type":"paragraph","content":[{"type":"text","text":"Copyright protects original works by identifiable authors for a limited term. Traditional cultural expressions are often collective, intergenerational and living, which makes them a poor fit."}]},{"type":"marginNote","attrs":{"kind":"cite"},"content":[{"type":"text","text":"See the Swakopmund Protocol (2010) on TCEs"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"A pattern can belong to a people long before it belongs to a label."}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Where the practical work is happening"}]},{"type":"paragraph","content":[{"type":"text","text":"Sui generis frameworks, community protocols and fair attribution clauses in design contracts are where the practical work is now happening."}]},{"type":"marginNote","attrs":{"kind":"note"},"content":[{"type":"text","text":"more on attribution clauses in a follow-up"}]}]}', 'Fashion has always borrowed. The question is when borrowing becomes taking, and who gets a say.
the whole question, really
Why the existing tools fall short
Copyright protects original works by identifiable authors for a limited term. Traditional cultural expressions are often collective, intergenerational and living, which makes them a poor fit.
See the Swakopmund Protocol (2010) on TCEs
A pattern can belong to a people long before it belongs to a label.
Where the practical work is happening
Sui generis frameworks, community protocols and fair attribution clauses in design contracts are where the practical work is now happening.
more on attribution clauses in a follow-up', 106, 'draft', 1, 3, 1);
INSERT INTO posts (id, slug, title, excerpt, category, tags, body_json, body_text, word_count, status, series_id, series_order, is_sample)
VALUES (2, 'what-the-copyright-tribunal-does-and-when-to-bring-a-dispute', 'What the Copyright Tribunal does, and when to bring a dispute', 'A plain guide to Kenya’s specialised forum for licensing and rights disputes.', 'Copyright', '["Copyright","Tribunal"]', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Copyright Tribunal is constituted under Section 48 of the Copyright Act (CAP 130)."}]},{"type":"marginNote","attrs":{"kind":"note"},"content":[{"type":"text","text":"CAP 130, s.48"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Matters the Tribunal hears"}]},{"type":"paragraph","content":[{"type":"text","text":"Disputes over licensing schemes, royalty rates and the conduct of collective management organisations are its core work."}]}]}', 'The Copyright Tribunal is constituted under Section 48 of the Copyright Act (CAP 130).
CAP 130, s.48
Matters the Tribunal hears
Disputes over licensing schemes, royalty rates and the conduct of collective management organisations are its core work.', 38, 'draft', NULL, NULL, 1);
INSERT INTO posts (id, slug, title, excerpt, category, tags, body_json, body_text, word_count, status, series_id, series_order, is_sample)
VALUES (3, 'licensing-music-for-film-and-digital-platforms-in-kenya', 'Licensing music for film and digital platforms in Kenya', 'Sync, master and performance rights, and the order to clear them in.', 'Entertainment', '["Music","Licensing"]', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every piece of music in a film carries at least two sets of rights: the composition and the recording."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Clear early"}]},{"type":"paragraph","content":[{"type":"text","text":"Licences negotiated after the edit is locked are licences negotiated without leverage."}]},{"type":"marginNote","attrs":{"kind":"note"},"content":[{"type":"text","text":"ask me how I know"}]}]}', 'Every piece of music in a film carries at least two sets of rights: the composition and the recording.
Clear early
Licences negotiated after the edit is locked are licences negotiated without leverage.
ask me how I know', 38, 'draft', NULL, NULL, 1);
INSERT INTO posts (id, slug, title, excerpt, category, tags, body_json, body_text, word_count, status, series_id, series_order, is_sample)
VALUES (4, 'counterfeits-supply-chains-and-cross-border-enforcement', 'Counterfeits, supply chains and cross-border enforcement', 'Why the fight against fakes now runs through logistics data.', 'Trademarks', '["Anti-counterfeiting","Design"]', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Counterfeit goods move through the same ports and platforms as genuine ones."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Working with customs"}]},{"type":"paragraph","content":[{"type":"text","text":"Recordal of marks with customs authorities remains one of the most cost-effective tools available to brand owners."}]},{"type":"marginNote","attrs":{"kind":"note"},"content":[{"type":"text","text":"Anti-Counterfeit Act, 2008"}]}]}', 'Counterfeit goods move through the same ports and platforms as genuine ones.
Working with customs
Recordal of marks with customs authorities remains one of the most cost-effective tools available to brand owners.
Anti-Counterfeit Act, 2008', 35, 'draft', 1, 2, 1);
INSERT INTO posts (id, slug, title, excerpt, category, tags, body_json, body_text, word_count, status, series_id, series_order, is_sample)
VALUES (5, 'what-boards-in-regulated-industries-should-ask-about', 'What boards in regulated industries should ask about intangible assets', 'Five questions for the audit committee.', 'Governance', '["Governance"]', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Intangible assets rarely appear on the agenda until something goes wrong."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Start with an inventory"}]},{"type":"paragraph","content":[{"type":"text","text":"A board cannot oversee what it has not listed."}]}]}', 'Intangible assets rarely appear on the agenda until something goes wrong.
Start with an inventory
A board cannot oversee what it has not listed.', 24, 'draft', NULL, NULL, 1);
