VALUES (6, 'protecting-a-design-collection-before-the-runway', 'Protecting a design collection before the runway', 'Registration, confidentiality and timing for emerging designers.', 'Fashion law', '["Design","Fashion law"]', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Showing a collection publicly can affect whether its designs can later be registered."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Timing matters"}]},{"type":"paragraph","content":[{"type":"text","text":"File first, then show."}]},{"type":"marginNote","attrs":{"kind":"note"},"content":[{"type":"text","text":"the single most useful line in this post"}]},{"type":"horizontalRule"},{"type":"figure","attrs":{"src":null,"key":null,"alt":"","caption":"Look book pages marked up before filing"}}]}', 'Showing a collection publicly can affect whether its designs can later be registered.
Timing matters
File first, then show.
the single most useful line in this post

Look book pages marked up before filing', 34, 'draft', 1, 1, 1);
